//! Serving of the prebuilt React islands assets.
//!
//! The real React bundle generated by npm/Vite is embedded into the web binary with `include_str!`.
//! This lets every screen hydrate without depending on an external CDN while keeping CSP `script-src 'self'`.

use axum::http::header::{CACHE_CONTROL, CONTENT_TYPE};
use axum::response::IntoResponse;

pub(crate) const APP_JS: &str = include_str!("../../assets/react/app.js");
// ⚠ The source map (`app.js.map`) is not served (task #593). There is no reason to hand out the original screen source in production.
//   The `sourceMappingURL` at the end of the bundle remains, but developer tools fetching it just get a 404.

#[derive(Clone, Copy)]
enum ReactAssetKind {
    JavaScript,
}

impl ReactAssetKind {
    fn content_type(self) -> &'static str {
        match self {
            Self::JavaScript => "text/javascript; charset=utf-8",
        }
    }

    fn cache_control(self) -> &'static str {
        match self {
            // `react_bootstrap.html` references the bundle with a `?v={asset_version}`
            // query, so the URL changes on every deploy (cache busting) and the body
            // can be cached long-term.
            Self::JavaScript => "public, max-age=31536000, immutable",
        }
    }

    fn body(self) -> &'static str {
        match self {
            Self::JavaScript => APP_JS,
        }
    }

    fn response(self) -> impl IntoResponse {
        (
            [
                (CONTENT_TYPE, self.content_type()),
                (CACHE_CONTROL, self.cache_control()),
            ],
            self.body(),
        )
    }
}

pub async fn app_js() -> impl IntoResponse {
    ReactAssetKind::JavaScript.response()
}
